package nz.tate.timezonehud;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a development client with this plugin loaded. Not a unit test -- it is the entry
 * point {@code ./gradlew run} uses, and it is the only way to verify the plugin in-game.
 */
public class TimezoneHudPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TimezoneHudPlugin.class);
		RuneLite.main(args);
	}
}

