package nz.tate.timezonehud;

import java.util.HashMap;
import java.util.Map;

/**
 * Stands in for RuneLite's ConfigManager. Values survive a new store being built over the
 * same map, which is what makes "does this really persist" testable.
 */
class MapConfigValues implements ConfigValues
{
	private final Map<String, String> saved = new HashMap<>();

	@Override
	public String get(String key)
	{
		return saved.get(key);
	}

	@Override
	public void put(String key, String value)
	{
		saved.put(key, value);
	}
}

